"""Read ids.txt and print the next sequential order id."""

from pathlib import Path

CHARS = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'


def increment(suffix: str) -> str:
    """Increment a string of ID characters, e.g. '243G' -> '243H'."""
    chars = list(suffix)
    for i in range(len(chars) - 1, -1, -1):
        idx = CHARS.find(chars[i])
        if idx == -1:
            raise ValueError(f"Unexpected character {chars[i]!r} in id suffix")
        if idx < len(CHARS) - 1:
            chars[i] = CHARS[idx + 1]
            return ''.join(chars)
        # wrap: this position rolls to '0', carry to position before it
        chars[i] = '0'
    # All positions wrapped – prepend an extra character
    return '1' + ''.join(chars)


def main() -> None:
    ids_path = Path('ids.txt')
    ids = [line.strip() for line in ids_path.read_text().splitlines() if line.strip()]

    if not ids:
        next_id = 'ORD-0001'
    else:
        last = ids[-1]
        prefix, sep, suffix = last.partition('-')
        if not sep or len(suffix) != 4:
            raise ValueError(f"Unexpected id format: {last!r}")
        next_id = f'{prefix}-{increment(suffix)}'

    print(next_id)


if __name__ == '__main__':
    main()

