import sys
import re


def next_id(last_id: str) -> str:
    """Given an ID like ORD-243G, return the next one."""
    m = re.fullmatch(r'(ORD-)([0-9A-Z]+)', last_id.strip())
    if not m:
        raise ValueError(f"Invalid ID format: {last_id!r}")

    prefix, suffix = m.group(1), m.group(2)
    chars = list(suffix)

    # Characters in increment order: 0-9 then A-Z
    alphabet = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'

    for i in range(len(chars) - 1, -1, -1):
        pos = alphabet.find(chars[i])
        if pos == -1:
            raise ValueError(f"Unexpected character {chars[i]!r} in ID")
        if pos < len(alphabet) - 1:
            chars[i] = alphabet[pos + 1]
            return prefix + ''.join(chars)
        else:
            chars[i] = alphabet[0]  # carry over

    # All positions rolled over – prepend a new digit
    return prefix + alphabet[0] + ''.join(chars)


def main():
    try:
        with open('ids.txt') as f:
            lines = [line.strip() for line in f if line.strip()]
    except FileNotFoundError:
        print('ORD-0000')
        return

    if not lines:
        print('ORD-0000')
        return

    last = lines[-1]
    # If the last line has leading line number (tab-separated), extract the ID
    parts = last.split('\t')
    last_id = parts[-1] if len(parts) > 1 else parts[0]

    print(next_id(last_id))


if __name__ == '__main__':
    main()
