#!/usr/bin/env python3
"""Generate manifest.json with SHA-256 digests for all files under release/."""

import hashlib
import json
from pathlib import Path

RELEASE_DIR = Path("release")
MANIFEST_PATH = Path("manifest.json")


def sha256_digest(path: Path) -> str:
    """Return the hex SHA-256 digest of a file."""
    h = hashlib.sha256()
    with path.open("rb") as f:
        for block in iter(lambda: f.read(65536), b""):
            h.update(block)
    return h.hexdigest()


def main() -> None:
    if not RELEASE_DIR.is_dir():
        print(f"Error: {RELEASE_DIR} does not exist.")
        raise SystemExit(1)

    manifest = {}
    for path in sorted(RELEASE_DIR.rglob("*")):
        if path.is_file():
            rel_path = str(path.relative_to(RELEASE_DIR))
            manifest[rel_path] = sha256_digest(path)

    with MANIFEST_PATH.open("w") as f:
        json.dump(manifest, f, indent=2)
        f.write("\n")

    print(f"Wrote {MANIFEST_PATH} with {len(manifest)} entries.")


if __name__ == "__main__":
    main()

