#!/usr/bin/env python3
"""List files under reports/ in report order."""

import os
import re
import pathlib


def report_sort_key(filename: str) -> tuple[int, str]:
    """Sort key: numeric part first, then the full name as tiebreaker."""
    match = re.search(r"report-(\d+)", filename)
    if match:
        return (int(match.group(1)), filename)
    return (float("inf"), filename)


def main() -> None:
    reports_dir = pathlib.Path("reports")
    if not reports_dir.is_dir():
        return

    files = sorted(os.listdir(reports_dir), key=report_sort_key)
    for f in files:
        print(f)


if __name__ == "__main__":
    main()

