"""Rotate old entries from app.log into archive.log.

Usage: python rotate.py AS_OF

AS_OF is a Unix timestamp in integer seconds. Every line of app.log starts
with a timestamp formatted YYYY-MM-DD HH:MM:SS followed by a message. Entries
strictly older than 7 days before AS_OF are moved to archive.log (appending,
preserving order), and app.log is rewritten with the remaining entries in their
original order.
"""

import sys
from datetime import datetime, timezone


def parse_timestamp(line: str) -> datetime | None:
    """Parse the leading 'YYYY-MM-DD HH:MM:SS' from a log line."""
    if len(line) < 19:
        return None
    try:
        return datetime.strptime(line[:19], "%Y-%m-%d %H:%M:%S").replace(
            tzinfo=timezone.utc
        )
    except ValueError:
        return None


def main() -> None:
    if len(sys.argv) != 2:
        print(f"Usage: python {sys.argv[0]} AS_OF", file=sys.stderr)
        sys.exit(1)

    try:
        as_of = int(sys.argv[1])
    except ValueError:
        print(f"Error: AS_OF must be an integer Unix timestamp", file=sys.stderr)
        sys.exit(1)

    cutoff_ts = as_of - 7 * 24 * 3600  # 7 days before AS_OF

    app_path = "app.log"
    archive_path = "archive.log"

    try:
        with open(app_path) as f:
            lines = f.readlines()
    except FileNotFoundError:
        print(f"Error: {app_path} not found", file=sys.stderr)
        sys.exit(1)

    keep: list[str] = []
    move: list[str] = []

    for line in lines:
        if line.strip() == "":
            # Preserve blank lines in place (treat as keep)
            keep.append(line)
            continue

        dt = parse_timestamp(line)
        if dt is None:
            # Lines that don't parse are kept in app.log
            keep.append(line)
        elif dt.timestamp() < cutoff_ts:
            move.append(line)
        else:
            keep.append(line)

    if move:
        with open(archive_path, "a") as f:
            f.writelines(move)

    with open(app_path, "w") as f:
        f.writelines(keep)


if __name__ == "__main__":
    main()

